(()=>{
const view=document.querySelector('#town-view'),world=document.querySelector('#town-world');if(!view||!world)return;
const reduced=matchMedia('(prefers-reduced-motion:reduce)');
const veil=document.createElement('div');veil.id='place-transition';veil.setAttribute('aria-hidden','true');veil.innerHTML='<i></i><span></span>';document.body.append(veil);
const transitionNames=['潮水入画','云过塔影','山海翻页','取景定格','胶片亮起','砖纹铺展','灯火引路','烟火升腾','小狮相迎','旧梦浮光','幕布开启','布纹掠过','海风收卷'];
window.addEventListener('town-open',e=>{if(reduced.matches)return;veil.className='kind-'+(e.detail%5);veil.querySelector('span').textContent=transitionNames[e.detail]||'翻开故事';veil.classList.remove('active');void veil.offsetWidth;veil.classList.add('active');setTimeout(()=>veil.classList.remove('active'),950)},true);
const parallax=document.createElement('div');parallax.className='map-parallax';parallax.innerHTML='<i class="near-foliage f1"></i><i class="near-foliage f2"></i><i class="sea-haze"></i>';world.append(parallax);
if(!reduced.matches&&matchMedia('(pointer:fine)').matches)view.addEventListener('pointermove',e=>{const r=view.getBoundingClientRect(),px=(e.clientX-r.left)/r.width-.5,py=(e.clientY-r.top)/r.height-.5;parallax.style.setProperty('--px',px);parallax.style.setProperty('--py',py)});
const lanterns=document.createElement('div');lanterns.className='street-lanterns';[[712,187],[824,220],[1224,126],[517,527],[1045,552],[1330,442]].forEach(([x,y],i)=>{const l=document.createElement('i');l.style.cssText=`left:${x}px;top:${y}px;--d:${i*.35}s`;lanterns.append(l)});world.append(lanterns);
let tour=false,timer=0,index=0;const tourButton=document.createElement('button');tourButton.id='town-tour';tourButton.textContent='自动巡游';document.querySelector('.town-buttons')?.append(tourButton);
function stopTour(message='已退出自动巡游'){tour=false;clearTimeout(timer);tourButton.textContent='自动巡游';tourButton.setAttribute('aria-pressed','false');window.townExperience?.restore();if(message)window.townExperience.status.textContent=message}
function tourStep(){if(!tour)return;const api=window.townExperience,n=api?.npcs[index%api.npcs.length];if(!n){stopTour('巡游暂时不可用');return}api.focus(n);api.status.textContent=`巡游第 ${index%api.npcs.length+1} 站 · ${n.name}`;world.classList.toggle('old-street-zone',index%api.npcs.length===1||index%api.npcs.length===4);timer=setTimeout(()=>{if(!tour)return;api.chat(n,false);timer=setTimeout(()=>{document.querySelector('#npc-talk').hidden=true;api.restore();index++;tourStep()},4300)},2200)}
tourButton.onclick=()=>{if(tour){stopTour();return}tour=true;index=0;tourButton.textContent='停止巡游';tourButton.setAttribute('aria-pressed','true');tourStep()};
view.addEventListener('pointerdown',()=>{if(tour)stopTour('已切换为自由探索')},{capture:true});window.addEventListener('keydown',e=>{if(tour&&['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','w','a','s','d'].includes(e.key))stopTour('已切换为自由探索')},true);
const met=new Set();const stampNames=['塔','街','海','衣','味','影'];const stampBox=document.querySelector('#journey-stamps');if(stampBox)stampBox.innerHTML=stampNames.map((x,i)=>`<i class="journey-stamp" data-stamp="${i}" style="--r:${[-7,4,-3,6,-5,3][i]}deg">${x}</i>`).join('');function updateJourney(){document.querySelector('#journey-count')?.replaceChildren(document.createTextNode(`${met.size} / 6`));document.querySelectorAll('.journey-stamp').forEach((x,i)=>x.classList.toggle('met',met.has(i)));document.querySelectorAll('.npc').forEach((x,i)=>x.classList.toggle('met',met.has(i)))}window.addEventListener('npc-met',e=>{met.add(e.detail);updateJourney()});updateJourney();
const townStatus=document.querySelector('#town-status');if(townStatus)new MutationObserver(()=>{townStatus.classList.remove('status-pulse');void townStatus.offsetWidth;townStatus.classList.add('status-pulse')}).observe(townStatus,{childList:true,characterData:true,subtree:true});
const observer=new MutationObserver(()=>{const p=document.querySelector('#player');if(!p)return;const x=parseFloat(p.style.left)||0,y=parseFloat(p.style.top)||0;world.classList.toggle('near-sea',x>1000&&y<520);world.classList.toggle('near-market',y>600);world.classList.toggle('near-oldtown',x>430&&x<1120&&y<600)});observer.observe(document.querySelector('#player'),{attributes:true,attributeFilter:['style']});
})();
